cat > "$TMPDIR/check.mjs" <<'EOF'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
for (const viewport of [{ width: 1280, height: 800 }, { width: 390, height: 844 }]) {
  const page = await browser.newPage({ viewport });
  await page.goto(`http://127.0.0.1:${process.env.PORT}/products.html`);
  const out = await page.$$eval('.page-products .section-title', els => els.map(el => {
    const s = getComputedStyle(el);
    return { text: el.textContent, fontSize: s.fontSize, letterSpacing: s.letterSpacing, textTransform: s.textTransform };
  }));
  console.log(viewport.width, JSON.stringify(out));
  await page.close();
}
await browser.close();
EOF
